@if($settings['enabled'] ?? true)<details class="theme-filters theme-container" open data-theme-block="product_filters"><summary>فیلتر محصولات</summary><form method="GET" action="{{ url()->current() }}"><label>دسته‌بندی<select name="category"><option value="">همه</option>@foreach($categories as $item)<option value="{{ $item->slug }}" @selected(($activeFilters['category'] ?? '') === $item->slug)>{{ $item->name }}</option>@endforeach</select></label><label>برند<select name="brand"><option value="">همه</option>@foreach($brands as $brand)<option value="{{ $brand->slug }}" @selected(($activeFilters['brand'] ?? '') === $brand->slug)>{{ $brand->name }}</option>@endforeach</select></label><label>حداقل قیمت<input type="number" min="0" name="min_price" value="{{ $activeFilters['min_price'] ?? '' }}"></label><label>حداکثر قیمت<input type="number" min="0" name="max_price" value="{{ $activeFilters['max_price'] ?? '' }}"></label><label><input type="checkbox" name="availability" value="in_stock" @checked(($activeFilters['availability'] ?? '') === 'in_stock')> فقط موجود</label><label><input type="checkbox" name="discounted" value="1" @checked($activeFilters['discounted'] ?? false)> تخفیف‌دار</label>@if($activeFilters['sort'] ?? null)<input type="hidden" name="sort" value="{{ $activeFilters['sort'] }}">@endif<button type="submit">اعمال فیلتر</button><a href="{{ url()->current() }}">پاک کردن فیلترها</a></form></details>@endif
